
import { useState, type FormEvent } from "react";
import { Link, useNavigate } from "react-router-dom";
import { useAuth } from "../hooks/useAuth";
import toast from "react-hot-toast";

const DEE_LOGO = "data:image/png;base64,";

const DEPARTMENTS = [
  "Business Strategy",
  "Maintenance",
  "Vendor Relations",
  "Customer Relations",
  "I.T ERP",
  "Skids & Pilot Plant",
  "Operations",
  "Design & Engineering",
  "Quality",
  "Bending",
  "Employee Relations",
  "I.T.",
  "Projects",
  "HR & Admin",
  "Finance",
  "CMD's Office",
];

const ROLES = [
  { value: "EMPLOYEE", label: "Employee" },
  { value: "HOD", label: "Head of Department (HOD)" },
  { value: "DIRECTOR", label: "Director" },
  { value: "TRAVEL_MANAGER", label: "Travel Manager" },
];

const GRADES = [1, 2, 3, 4, 5, 6, 7, 8];

const PLANTS = [
  "Palwal Plant",
  "Assam Plant",
  "Anjar Plant",
  "Chennai Plant",
];

type SignupForm = {
  name: string;
  email: string;
  password: string;
  confirmPassword: string;
  role: string;
  department: string;
  grade: string;
  plant: string;
};

const initialForm: SignupForm = {
  name: "",
  email: "",
  password: "",
  confirmPassword: "",
  role: "EMPLOYEE",
  department: "",
  grade: "",
  plant: "",
};

const inputCls =
  "w-full px-4 py-2.5 border border-gray-200 rounded text-xs text-gray-800 placeholder-gray-400 focus:outline-none focus:ring-2 focus:ring-blue-400 focus:border-transparent transition";

export default function Signup() {
  const [form, setForm] = useState<SignupForm>({ ...initialForm });
  const [loading, setLoading] = useState(false);

  const { signup } = useAuth();
  const navigate = useNavigate();

  const set = (field: keyof SignupForm, value: string) => {
    setForm((prev) => ({
      ...prev,
      [field]: value,
    }));
  };

  const handleRoleChange = (role: string) => {
    setForm((prev) => ({
      ...prev,
      role,
      department: role === "DIRECTOR" ? "" : prev.department,
      grade: role === "DIRECTOR" ? "" : prev.grade,
      plant: role === "DIRECTOR" ? "" : prev.plant,
    }));
  };

  const handleSubmit = async (e: FormEvent<HTMLFormElement>) => {
    e.preventDefault();

    if (!form.name.trim()) {
      toast.error("Please enter your full name");
      return;
    }

    if (!form.email.trim()) {
      toast.error("Please enter your company email");
      return;
    }

    if (form.password.length < 8) {
      toast.error("Password must be at least 8 characters");
      return;
    }

    if (form.password !== form.confirmPassword) {
      toast.error("Passwords do not match");
      return;
    }

    if (form.role !== "DIRECTOR") {
      if (!form.department) {
        toast.error("Please select your department");
        return;
      }

      if (!form.plant) {
        toast.error("Please select your plant");
        return;
      }

      if (!form.grade) {
        toast.error("Please select your grade");
        return;
      }
    }

    setLoading(true);

    try {
    
const signupData = {
  ...form,
  name: form.name.trim(),
  email: form.email.trim(),
  department:
    form.role === "DIRECTOR" ? "" : form.department,
  grade:
    form.role === "DIRECTOR" ? undefined : Number(form.grade),
  plant: form.role === "DIRECTOR" ? "" : form.plant,
};


      await signup(signupData);

      toast.success(
        "Registration submitted! Waiting for admin approval."
      );

      navigate("/login");
    } catch (err: unknown) {
      const error = err as {
        response?: {
          data?: {
            error?: string;
            message?: string;
          };
        };
        message?: string;
      };

      toast.error(
        error.response?.data?.error ||
          error.response?.data?.message ||
          error.message ||
          "Signup failed. Please try again."
      );
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-[#eef2f7] flex flex-col">
      {/* HEADER */}
      <header className="mt-4 bg-[#0b2c4a] text-white py-3 px-4 shadow-md">
        <div className="flex items-center justify-center gap-3">
          <img
            src={DEE_LOGO}
            alt="DEE logo"
            className="h-11 w-11 shrink-0 object-contain"
          />
          <div className="text-left">
            <h1 className="text-xl tracking-wide font-semibold leading-tight">
              <span className="text-red-500">DEE</span>{" "}
              <span className="text-white">PIPING SYSTEM</span>
            </h1>
            <p className="text-xs text-gray-300 font-bold mt-1">
              Inhouse Travel Management Platform
            </p>
          </div>
        </div>
      </header>

      {/* SIGNUP CARD */}
      <main className="flex-1 flex items-center justify-center px-4 py-8">
        <div className="bg-white shadow-md w-full max-w-md p-8">
          <h2 className="text-xl font-bold text-gray-900 text-center mb-1">
            Create Account
          </h2>

          <p className="text-xs text-gray-400 text-center mb-6">
            Fill in the details below to get started
          </p>

          <form onSubmit={handleSubmit} className="space-y-3">
            {/* FULL NAME */}
            <div>
              <label className="block text-xs font-semibold text-gray-500 mb-1">
                Full Name
              </label>

              <input
                type="text"
                value={form.name}
                placeholder="e.g. Amit Sharma"
                onChange={(e) => set("name", e.target.value)}
                autoComplete="name"
                required
                className={inputCls}
              />
            </div>

            {/* EMAIL */}
            <div>
              <label className="block text-xs font-semibold text-gray-500 mb-1">
                Company Email ID
              </label>

              <input
                type="email"
                value={form.email}
                placeholder="amit@deepiping.com"
                onChange={(e) => set("email", e.target.value)}
                autoComplete="email"
                required
                className={inputCls}
              />
            </div>

            {/* ROLE */}
            <div>
              <label className="block text-xs font-semibold text-gray-500 mb-1">
                Role
              </label>

              <select
                value={form.role}
                onChange={(e) => handleRoleChange(e.target.value)}
                className={inputCls}
              >
                {ROLES.map((role) => (
                  <option key={role.value} value={role.value}>
                    {role.label}
                  </option>
                ))}
              </select>
            </div>

            {/* DEPARTMENT - HIDDEN FOR DIRECTOR */}
            {form.role !== "DIRECTOR" && (
              <div>
                <label className="block text-xs font-semibold text-gray-500 mb-1">
                  Department <span className="text-red-500">*</span>
                </label>

                <select
                  value={form.department}
                  onChange={(e) => set("department", e.target.value)}
                  required
                  className={inputCls}
                >
                  <option value="">Select Department</option>

                  {DEPARTMENTS.map((department) => (
                    <option key={department} value={department}>
                      {department}
                    </option>
                  ))}
                </select>
              </div>
            )}

            {/* DIRECTOR INFORMATION */}
            {form.role === "DIRECTOR" && (
              <div className="px-3 py-2.5 bg-blue-50 border border-blue-100 rounded">
                <p className="text-xs text-blue-700">
                  Directors are not assigned to a department, grade, or plant.
                </p>
              </div>
            )}

            {/* PLANT - HIDDEN FOR DIRECTOR */}
            {form.role !== "DIRECTOR" && (
              <div>
                <label className="block text-xs font-semibold text-gray-500 mb-1">
                  Plant <span className="text-red-500">*</span>
                </label>

                <div className="grid grid-cols-2 gap-2">
                  {PLANTS.map((plant) => (
                    <button
                      key={plant}
                      type="button"
                      onClick={() => set("plant", plant)}
                      aria-pressed={form.plant === plant}
                      className={`py-2.5 px-2 rounded text-xs font-semibold border-2 transition text-center ${
                        form.plant === plant
                          ? "border-blue-500 bg-blue-600 text-white"
                          : "border-gray-200 bg-white text-gray-500 hover:border-blue-300 hover:text-blue-600"
                      }`}
                    >
                      {plant}
                    </button>
                  ))}
                </div>

                {form.plant && (
                  <p className="text-xs text-blue-600 font-medium mt-1.5">
                    ✓ {form.plant} selected
                  </p>
                )}
              </div>
            )}

            {/* GRADE - HIDDEN FOR DIRECTOR */}
            {form.role !== "DIRECTOR" && (
              <div>
                <label className="block text-xs font-semibold text-gray-500 mb-1">
                  Employee Grade <span className="text-red-500">*</span>
                </label>

                <div className="grid grid-cols-8 gap-1.5">
                  {GRADES.map((grade) => (
                    <button
                      key={grade}
                      type="button"
                      onClick={() => set("grade", String(grade))}
                      aria-pressed={form.grade === String(grade)}
                      className={`py-2 rounded text-xs font-bold border-2 transition ${
                        form.grade === String(grade)
                          ? "border-blue-500 bg-blue-600 text-white"
                          : "border-gray-200 bg-white text-gray-500 hover:border-blue-300 hover:text-blue-600"
                      }`}
                    >
                      {grade}
                    </button>
                  ))}
                </div>

                {form.grade ? (
                  <p className="text-xs text-blue-600 font-medium mt-1.5">
                    ✓ Grade {form.grade} selected
                  </p>
                ) : (
                  <p className="text-xs text-gray-400 mt-1.5">
                    Select your grade
                  </p>
                )}
              </div>
            )}

            {/* PASSWORDS */}
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
              <div>
                <label className="block text-xs font-semibold text-gray-500 mb-1">
                  Password
                </label>

                <input
                  type="password"
                  value={form.password}
                  placeholder="Min 8 characters"
                  onChange={(e) => set("password", e.target.value)}
                  autoComplete="new-password"
                  minLength={8}
                  required
                  className={inputCls}
                />
              </div>

              <div>
                <label className="block text-xs font-semibold text-gray-500 mb-1">
                  Confirm Password
                </label>

                <input
                  type="password"
                  value={form.confirmPassword}
                  placeholder="Repeat password"
                  onChange={(e) =>
                    set("confirmPassword", e.target.value)
                  }
                  autoComplete="new-password"
                  minLength={8}
                  required
                  className={inputCls}
                />
              </div>
            </div>

            {/* SUBMIT */}
            <button
              type="submit"
              disabled={loading}
              className="w-full py-2.5 mt-1 bg-blue-600 hover:bg-blue-700 text-white text-sm font-semibold rounded transition disabled:opacity-60 disabled:cursor-not-allowed"
            >
              {loading ? "Submitting..." : "Create Account"}
            </button>
          </form>

          {/* LOGIN LINK */}
          <p className="text-xs text-center text-gray-400 mt-5">
            Already have an account?{" "}
            <Link
              to="/login"
              className="text-blue-600 hover:underline font-medium"
            >
              Login
            </Link>
          </p>
        </div>
      </main>

      {/* FOOTER */}
      <footer className="text-center py-3 text-xs text-gray-400 border-t border-gray-200 bg-white">
        © {new Date().getFullYear()} DEE Piping System · All rights reserved
      </footer>
    </div>
  );
}
